type SessionUser = {id:string;username:string;display_name:string;role:string;avatar_url?:string|null};
function AuthScreen({onAuth}:{onAuth:(user:SessionUser,token:string)=>void}){
 const [mode,setMode]=useState<"login"|"register">("login");
 const [username,setUsername]=useState("");
 const [password,setPassword]=useState("");
 const [displayName,setDisplayName]=useState("");
 const [setupCode,setSetupCode]=useState("");
 const [firstAccount,setFirstAccount]=useState(false);
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState("");
 useEffect(()=>{apiFetch("/auth/setup-status",{cache:"no-store"}).then(r=>r.json()).then(d=>setFirstAccount(!!d.first_account)).catch(()=>undefined)},[]);
 const submit=async()=>{
  if(busy)return;setBusy(true);setError("");
  try{
   const clean=username.trim().replace(/^@/,"").toLowerCase();
   if(!clean||!password)throw new Error("Укажи логин и пароль.");
   if(mode==="register"&&password.length<8)throw new Error("Пароль должен содержать не менее 8 символов.");
   const path=mode==="register"?"/auth/register":"/auth/login";
   const response=await apiFetch(path,{method:"POST",headers:{"Content-Type":"application/json"},cache:"no-store",body:JSON.stringify(mode==="register"?{username:clean,password,display_name:displayName.trim()||clean,setup_code:setupCode}:{username:clean,password})});
   const data=await response.json().catch(()=>({}));
   if(!response.ok)throw new Error(typeof data.error==="string"?data.error:data.error?.message||"Не удалось выполнить вход.");
   localStorage.setItem("ai_bragina_token",data.token);
   localStorage.setItem("ai_bragina_user",JSON.stringify(data.user));
   onAuth(data.user,data.token);
  }catch(e){setError(e instanceof Error?e.message:"Ошибка соединения.");}
  finally{setBusy(false);}
 };
 return <div className="auth-screen"><div className="auth-glow"/><div className="auth-card"><div className="auth-brand"><div className="auth-seal">✦</div><div><b>СОЮЗ</b><small>ЕДИНАЯ ЦИФРОВАЯ СИСТЕМА</small></div></div><div className="eyebrow">ЗАЩИЩЁННЫЙ ДОСТУП</div><h1>{mode==="login"?"С возвращением":"Создать аккаунт"}</h1><p className="auth-lead">{mode==="login"?"Войдите, чтобы продолжить работу в системе.":"Создайте личную учётную запись участника СОЮЗ."}</p><label className="auth-field">ЛОГИН<input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} placeholder="Ваш логин"/></label>{mode==="register"&&<label className="auth-field">ОТОБРАЖАЕМОЕ ИМЯ<input value={displayName} onChange={e=>setDisplayName(e.target.value)} placeholder="Как вас будут видеть"/></label>}<label className="auth-field">ПАРОЛЬ<input type="password" autoComplete={mode==="login"?"current-password":"new-password"} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Не менее 8 символов"/></label>{mode==="register"&&firstAccount&&<label className="auth-field">КОД ПЕРВОЙ НАСТРОЙКИ<input type="password" autoComplete="off" value={setupCode} onChange={e=>setSetupCode(e.target.value)} placeholder="Код владельца"/></label>}{error&&<div className="auth-error" role="alert">{error}</div>}<button className="hero-button auth-submit" disabled={busy} onClick={()=>void submit()}>{busy?"ПРОВЕРЯЕМ…":mode==="login"?"ВОЙТИ В СОЮЗ":"СОЗДАТЬ АККАУНТ"} <ArrowRight size={16}/></button><button className="auth-switch" onClick={()=>{setMode(mode==="login"?"register":"login");setError("")}}>{mode==="login"?"Нет аккаунта? Создать":"Уже зарегистрированы? Войти"}</button><small className="auth-foot">СОЕДИНЕНИЕ С СЕРВЕРОМ · ПЕРСОНАЛЬНАЯ УЧЁТНАЯ ЗАПИСЬ</small></div></div>;
}


type ChatSummary={id:string;peer_username:string;peer_display_name:string;peer_avatar?:string|null;last_message?:string|null;unread:number};
type ChatMessage={id:string;sender_id:string;body:string;created_at:string};
function MessagesView({token,user}:{token:string;user:SessionUser}){
 const [chats,setChats]=useState<ChatSummary[]>([]);
 const [selected,setSelected]=useState<ChatSummary|null>(null);
 const [messages,setMessages]=useState<ChatMessage[]>([]);
 const [search,setSearch]=useState("");
 const [matches,setMatches]=useState<Array<{id:string;username:string;display_name:string}>>([]);
 const [draft,setDraft]=useState("");
 const [error,setError]=useState("");
 const [busy,setBusy]=useState(false);
 const lastMessageAt=useRef("");
 const headers={Authorization:"Bearer "+token,"Content-Type":"application/json"};
 const loadChats=async()=>{try{const r=await apiFetch("/chat/list",{headers:{Authorization:"Bearer "+token},cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось загрузить чаты");setChats(d.chats||[]);}catch(e){setError(e instanceof Error?e.message:"Ошибка связи");}};
 useEffect(()=>{void loadChats();},[token]);
 const openChat=async(chat:ChatSummary)=>{lastMessageAt.current="";setSelected(chat);setError("");try{const r=await apiFetch("/chat/messages?thread_id="+encodeURIComponent(chat.id),{headers:{Authorization:"Bearer "+token},cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось загрузить сообщения");setMessages(d.messages||[]);lastMessageAt.current=d.messages?.at(-1)?.created_at||"";await apiFetch("/chat/read",{method:"POST",headers,body:JSON.stringify({thread_id:chat.id})});setChats(v=>v.map(c=>c.id===chat.id?{...c,unread:0}:c));}catch(e){setError(e instanceof Error?e.message:"Ошибка загрузки");}};
 useEffect(()=>{if(!selected)return;let live=true;let polling=false;const poll=async()=>{if(polling)return;polling=true;try{const r=await apiFetch("/chat/messages?thread_id="+encodeURIComponent(selected.id)+"&after="+encodeURIComponent(lastMessageAt.current),{headers:{Authorization:"Bearer "+token},cache:"no-store"});const d=await r.json();if(r.ok&&live&&Array.isArray(d.messages)&&d.messages.length){lastMessageAt.current=d.messages.at(-1)?.created_at||lastMessageAt.current;setMessages(v=>[...v,...d.messages]);}}catch{}finally{polling=false;}};const id=window.setInterval(()=>void poll(),10000);return()=>{live=false;window.clearInterval(id)};},[selected?.id,token]);
 const findUsers=async()=>{setError("");if(search.trim().length<2){setMatches([]);return;}try{const r=await apiFetch("/chat/users?q="+encodeURIComponent(search.trim()),{headers:{Authorization:"Bearer "+token},cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Поиск недоступен");setMatches(d.users||[]);}catch(e){setError(e instanceof Error?e.message:"Ошибка поиска");}};
 const startDirect=async(username:string)=>{setBusy(true);setError("");try{const r=await apiFetch("/chat/direct",{method:"POST",headers,body:JSON.stringify({username})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось открыть диалог");await loadChats();const chat:ChatSummary={id:d.thread.id,peer_username:d.thread.peer.username,peer_display_name:d.thread.peer.display_name,unread:0};setSearch("");setMatches([]);await openChat(chat);}catch(e){setError(e instanceof Error?e.message:"Ошибка создания диалога");}finally{setBusy(false);}};
 const sendMessage=async()=>{const body=draft.trim();if(!body||!selected||busy)return;setBusy(true);try{const r=await apiFetch("/chat/messages",{method:"POST",headers,body:JSON.stringify({thread_id:selected.id,body})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось отправить сообщение");setMessages(v=>[...v,d.message]);setDraft("");void loadChats();}catch(e){setError(e instanceof Error?e.message:"Ошибка отправки");}finally{setBusy(false);}};
 return <div className="messages-workspace"><div className="messages-sidebar"><div className="messages-search"><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&void findUsers()} placeholder="Найти участника по логину"/><button onClick={()=>void findUsers()} aria-label="Найти"><Search size={17}/></button></div>{matches.length>0&&<div className="chat-matches">{matches.map(m=><button key={m.id} onClick={()=>void startDirect(m.username)} disabled={busy}><b>{m.display_name}</b><small>@{m.username}</small></button>)}</div>}<div className="chat-list-title">ВАШИ ДИАЛОГИ <button onClick={()=>void loadChats()} aria-label="Обновить"><Activity size={15}/></button></div>{chats.length===0?<div className="chat-empty">Диалогов пока нет. Найдите участника по логину, чтобы начать общение.</div>:chats.map(c=><button key={c.id} className={"chat-list-item "+(selected?.id===c.id?"selected":"")} onClick={()=>void openChat(c)}><span className="chat-avatar">{(c.peer_display_name||c.peer_username||"С").slice(0,1).toUpperCase()}</span><span className="chat-preview"><b>{c.peer_display_name||c.peer_username}</b><small>{c.last_message||"Начните общение"}</small></span>{c.unread>0&&<i>{c.unread}</i>}</button>)}</div><div className="messages-thread">{selected?<><div className="thread-head"><button onClick={()=>setSelected(null)} className="thread-back">←</button><div><b>{selected.peer_display_name}</b><small>@{selected.peer_username}</small></div></div><div className="thread-messages">{messages.map(m=><div key={m.id} className={"thread-bubble "+(m.sender_id===user.id?"mine":"")}>{m.body}<small>{new Date(m.created_at).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</small></div>)}</div><div className="thread-compose"><input value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>e.key==="Enter"&&void sendMessage()} placeholder="Напишите сообщение…"/><button onClick={()=>void sendMessage()} disabled={busy||!draft.trim()} aria-label="Отправить"><Send size={18}/></button></div></>:<div className="thread-empty"><MessageCircle size={35}/><b>СВЯЗЬ СОЮЗА</b><span>Выберите диалог или найдите участника, чтобы начать общение</span></div>}</div>{error&&<div className="messages-error" role="alert">{error}</div>}</div>;
}


type VideoItem={id:string;title:string;author:string;thumbnail:string;embed:string;url:string;views:number;duration:number};

type CommunityPost={id:string;user_id:string;username:string;display_name:string;body:string;created_at:string;likes:number;comments:number;liked:number};
type CommunityComment={id:string;username:string;display_name:string;body:string;created_at:string};
function CommunityView({token,user}:{token:string;user:SessionUser}){
 const [posts,setPosts]=useState<CommunityPost[]>([]);
 const [draft,setDraft]=useState("");
 const [commentDraft,setCommentDraft]=useState("");
 const [expanded,setExpanded]=useState<string|null>(null);
 const [comments,setComments]=useState<CommunityComment[]>([]);
 const [error,setError]=useState("");
 const [busy,setBusy]=useState(false);
 const headers={Authorization:"Bearer "+token,"Content-Type":"application/json"};
 const load=async()=>{try{const r=await apiFetch("/community/posts",{headers:{Authorization:"Bearer "+token},cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось загрузить ленту");setPosts(d.posts||[]);}catch(e){setError(e instanceof Error?e.message:"Ошибка ленты");}};
 useEffect(()=>{void load();},[token]);
 const publish=async()=>{if(!draft.trim()||busy)return;setBusy(true);setError("");try{const r=await apiFetch("/community/posts",{method:"POST",headers,body:JSON.stringify({body:draft.trim()})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось опубликовать");setPosts(v=>[d.post,...v]);setDraft("");}catch(e){setError(e instanceof Error?e.message:"Ошибка публикации");}finally{setBusy(false);}};
 const like=async(post:CommunityPost)=>{try{const r=await apiFetch("/community/like",{method:"POST",headers,body:JSON.stringify({post_id:post.id})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось поставить отметку");setPosts(v=>v.map(p=>p.id===post.id?{...p,liked:d.liked?1:0,likes:d.likes}:p));}catch(e){setError(e instanceof Error?e.message:"Ошибка реакции");}};
 const toggleComments=async(postId:string)=>{if(expanded===postId){setExpanded(null);return;}setExpanded(postId);try{const r=await apiFetch("/community/comments?post_id="+encodeURIComponent(postId),{headers:{Authorization:"Bearer "+token},cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось загрузить комментарии");setComments(d.comments||[]);}catch(e){setError(e instanceof Error?e.message:"Ошибка комментариев");}};
 const sendComment=async(postId:string)=>{if(!commentDraft.trim()||busy)return;setBusy(true);try{const r=await apiFetch("/community/comments",{method:"POST",headers,body:JSON.stringify({post_id:postId,body:commentDraft.trim()})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось отправить комментарий");setComments(v=>[...v,d.comment]);setPosts(v=>v.map(p=>p.id===postId?{...p,comments:p.comments+1}:p));setCommentDraft("");}catch(e){setError(e instanceof Error?e.message:"Ошибка комментария");}finally{setBusy(false);}};
 return <div className="community-stream"><div className="community-compose"><span className="profile-avatar">{(user.display_name||user.username).slice(0,1).toUpperCase()}</span><textarea value={draft} onChange={e=>setDraft(e.target.value)} placeholder="Поделитесь новостью или идеей…" maxLength={3000}/><button onClick={()=>void publish()} disabled={busy||!draft.trim()}><Plus size={17}/> ОПУБЛИКОВАТЬ</button></div>{error&&<div className="messages-error">{error}</div>}{posts.length===0?<div className="feed-empty"><Users size={30}/><b>Лента пока пуста</b><span>Создайте первую публикацию в сообществе</span></div>:posts.map(p=><article className="feed-post" key={p.id}><div className="post-top"><div className="post-emblem">{(p.display_name||p.username).slice(0,1).toUpperCase()}</div><div><b>{p.display_name||p.username}</b><small>@{p.username} · {new Date(p.created_at).toLocaleString("ru-RU",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}</small></div></div><p className="community-post-body">{p.body}</p><div className="post-actions"><button className={p.liked?"is-liked":""} onClick={()=>void like(p)}>{p.liked?"♥":"♡"} {p.likes}</button><button onClick={()=>void toggleComments(p.id)}>◯ {p.comments} КОММЕНТАРИЕВ</button></div>{expanded===p.id&&<div className="comments-panel">{comments.map(c=><div className="comment-row" key={c.id}><b>{c.display_name||c.username}</b><span>{c.body}</span></div>)}<div className="comment-compose"><input value={commentDraft} onChange={e=>setCommentDraft(e.target.value)} onKeyDown={e=>e.key==="Enter"&&void sendComment(p.id)} placeholder="Написать комментарий…"/><button onClick={()=>void sendComment(p.id)} disabled={busy||!commentDraft.trim()}><Send size={15}/></button></div></div>}</article>)}</div>;
}

function VideoView(){
 const [topic,setTopic]=useState("trending");
 const [items,setItems]=useState<VideoItem[]>([]);
 const [playing,setPlaying]=useState<VideoItem|null>(null);
 const [page,setPage]=useState(1);
 const [loading,setLoading]=useState(false);
 const [error,setError]=useState("");
 const bind=useDrag(({swipe:[,sy]})=>{if(!playing||!items.length)return;const index=items.findIndex(v=>v.id===playing.id);if(sy<0)setPlaying(items[(index+1)%items.length]);else if(sy>0)setPlaying(null);},{axis:"y",filterTaps:true});
 const load=async(nextTopic=topic,nextPage=1)=>{if(loading)return;setLoading(true);setError("");try{const r=await apiFetch("/video/feed?topic="+encodeURIComponent(nextTopic)+"&page="+nextPage,{cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Видеолента временно недоступна");const rows=Array.isArray(d.results)?d.results:Array.isArray(d)?d:[];const normalized=rows.map((v:any)=>{const candidates=[v.id,v.video_id,v.code,v.video_url,v.url,v.embed_url].filter(Boolean);let id="";for(const value of candidates){const m=String(value).match(/[a-f0-9]{32}/i);if(m){id=m[0];break;}}if(!id)return null;const raw=v.duration||v.duration_seconds||0;const duration=typeof raw==="string"&&raw.includes(":")?raw.split(":").reduce((n:number,p:string)=>n*60+Number(p||0),0):Number(raw)||0;if(duration>150)return null;return{id,title:String(v.title||v.name||"Короткое видео"),author:String(v.author?.name||v.author_name||v.channel_name||"Автор не указан"),thumbnail:v.thumbnail_url||v.picture_url||v.poster_url||v.thumbnail||"",embed:"https://rutube.ru/play/embed/"+id+"/",url:"https://rutube.ru/video/"+id+"/",views:Number(v.hits||v.views_count||v.views||0),duration};}).filter(Boolean) as VideoItem[];setItems(nextPage===1?normalized:[...items,...normalized]);setPage(nextPage);if(!normalized.length&&nextPage===1)setError("В этой подборке пока нет доступных коротких роликов.");}catch(e){setError(e instanceof Error?e.message:"Ошибка загрузки видеоленты");}finally{setLoading(false);}};
 useEffect(()=>{void load("trending",1);},[]);
 const choose=(v:string)=>{setTopic(v);setItems([]);setPlaying(null);setPage(1);void load(v,1);};
 return <div className="generic-page video-page"><div className="eyebrow">МЕДИАПРОСТРАНСТВО СОЮЗА</div><h1>ВИДЕОЛЕНТА</h1><p className="lead">Короткие открытые видеоролики из каталога RUTUBE. Видео воспроизводится на площадке источника.</p><div className="video-topics">{[{id:"trending",label:"ПОПУЛЯРНОЕ"},{id:"fun",label:"ЮМОР"},{id:"animals",label:"ЖИВОТНЫЕ"},{id:"auto",label:"АВТО"},{id:"useful",label:"ПОЛЕЗНОЕ"}].map(t=><button key={t.id} className={topic===t.id?"active":""} onClick={()=>choose(t.id)}>{t.label}</button>)}</div>{playing&&<div className="video-player"><div className="video-player-head" {...bind()}><b>{playing.title}</b><button onClick={()=>setPlaying(null)}>ЗАКРЫТЬ ×</button></div><iframe src={playing.embed} title={playing.title} allow="autoplay; fullscreen; picture-in-picture" allowFullScreen loading="lazy"/></div>}{error&&<div className="video-error">{error}</div>}<div className="video-grid">{items.map(v=><button key={v.id} className="video-card" onClick={()=>setPlaying(v)}><div className="video-thumb">{v.thumbnail?<img src={v.thumbnail} alt="" loading="lazy"/>:<div className="video-no-thumb"><Play size={25}/></div>}<span><Play size={17}/></span></div><b>{v.title}</b><small>{v.author} · {v.views.toLocaleString("ru-RU")} просмотров</small></button>)}</div>{loading&&<div className="video-loading">ЗАГРУЖАЕМ ПОДБОРКУ…</div>}{!loading&&items.length>0&&page<5&&<button className="outline-btn video-more" onClick={()=>void load(topic,page+1)}>ПОКАЗАТЬ ЕЩЁ <ArrowRight size={15}/></button>}</div>;
}


type PlannerGuest={id:string;name:string;kind:"adult"|"child";status:"invited"|"confirmed"|"declined"|"no_show";count:number;note?:string};
type PlannerEvent={id:string;name:string;type?:string;date:string;city:string;budget:string;guests:string;guestList?:PlannerGuest[];adults?:number;children?:number;menuLevel?:string;wishes?:string;beverages?:boolean;menu:string;shopping:string;tasks:string;archived:boolean;updatedAt:number};
type SavedCase={id:string;vehicle:string;symptoms:string;codes:string;answer:string;createdAt:number;status:string};
function SpecialistWorkspace({kind,onNotify}:{kind:"chef"|"mechanic";onNotify:(s:string)=>void}){
 const [mode,setMode]=useState(kind==="chef"?"home":"diagnosis");
 const [busy,setBusy]=useState(false),[error,setError]=useState(""),[answer,setAnswer]=useState("");
 const [events,setEvents]=useState<PlannerEvent[]>(()=>{try{return JSON.parse(localStorage.getItem("soyuz_chef_events_v1")||"[]")}catch{return[]}});
 const [cases,setCases]=useState<SavedCase[]>(()=>{try{return JSON.parse(localStorage.getItem("soyuz_mechanic_cases_v1")||"[]")}catch{return[]}});
 const [eventName,setEventName]=useState(""),[eventDate,setEventDate]=useState(""),[eventCity,setEventCity]=useState(""),[eventBudget,setEventBudget]=useState("");
  const [eventType,setEventType]=useState("День рождения"),[eventAdults,setEventAdults]=useState("2"),[eventChildren,setEventChildren]=useState("0"),[eventMenuLevel,setEventMenuLevel]=useState("standard"),[eventWishes,setEventWishes]=useState(""),[eventBeverages,setEventBeverages]=useState(false);
 const [selected,setSelected]=useState<string|null>(null);
  const [guestName,setGuestName]=useState(""),[guestKind,setGuestKind]=useState<"adult"|"child">("adult"),[guestCount,setGuestCount]=useState("1"),[guestNote,setGuestNote]=useState("");
 const [ingredients,setIngredients]=useState(""),[dish,setDish]=useState(""),[servings,setServings]=useState("2");
 const [vehicle,setVehicle]=useState(""),[symptoms,setSymptoms]=useState(""),[codes,setCodes]=useState("");
 useEffect(()=>{localStorage.setItem("soyuz_chef_events_v1",JSON.stringify(events))},[events]);
 useEffect(()=>{localStorage.setItem("soyuz_mechanic_cases_v1",JSON.stringify(cases))},[cases]);
 const ask=async(prompt:string,system:string)=>{
  if(busy||!prompt.trim())return;setBusy(true);setError("");setAnswer("");
  try{const token=localStorage.getItem("ai_bragina_token")||"";const r=await apiFetch("/",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({model:"openai/gpt-oss-120b",messages:[{role:"system",content:system+" Отвечай по-русски, структурированно, конкретно и безопасно."},{role:"user",content:prompt}],temperature:.35,max_tokens:2200})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error?.message||d.error||"ИИ-сервис временно недоступен");const text=d.choices?.[0]?.message?.content;if(!text)throw new Error("Пустой ответ ИИ");setAnswer(text);if(d.usage)void apiFetch("/usage",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({usage:d.usage,model:"openai/gpt-oss-120b",page:kind+"-"+mode})}).catch(()=>undefined);
  }catch(e){setError(e instanceof Error?e.message:"Ошибка запроса")}finally{setBusy(false)}
 };
 const createEvent=()=>{if(!eventName.trim()){setError("Укажите название мероприятия");return}const e:PlannerEvent={id:crypto.randomUUID(),name:eventName.trim(),type:eventType,date:eventDate,city:eventCity,budget:eventBudget,guests:"",adults:Math.max(0,Number(eventAdults)||0),children:Math.max(0,Number(eventChildren)||0),menuLevel:eventMenuLevel,wishes:eventWishes,beverages:eventBeverages,guestList:[],menu:"",shopping:"",tasks:"",archived:false,updatedAt:Date.now()};setEvents(v=>[e,...v]);setSelected(e.id);setEventName("");setMode("events");setError("")};
 const current=events.find(e=>e.id===selected);
 const patchEvent=(patch:Partial<PlannerEvent>)=>setEvents(v=>v.map(e=>e.id===selected?{...e,...patch,updatedAt:Date.now()}:e));
  const addGuest=()=>{if(!current)return;const name=guestName.trim();const count=Math.max(1,Math.min(500,Math.floor(Number(guestCount)||1)));if(!name){setError("Укажите имя гостя");return;}patchEvent({guestList:[...(current.guestList||[]),{id:crypto.randomUUID(),name,kind:guestKind,status:"invited",count,note:guestNote.trim()}]});setGuestName("");setGuestCount("1");setGuestNote("");setError("");};
  const updateGuest=(id:string,patch:Partial<PlannerGuest>)=>{if(!current)return;patchEvent({guestList:(current.guestList||[]).map(g=>g.id===id?{...g,...patch}:g)});};
  const removeGuest=(id:string)=>{if(!current)return;patchEvent({guestList:(current.guestList||[]).filter(g=>g.id!==id)});};
  const guestTotals=(list:PlannerGuest[])=>(list||[]).reduce((a,g)=>{if(g.status==="declined"||g.status==="no_show")return a;a[g.kind]+=g.count;return a;},{adult:0,child:0});
 const saveCase=()=>{if(!vehicle.trim()||!symptoms.trim()){setError("Укажите автомобиль и симптомы неисправности");return}setCases(v=>[{id:crypto.randomUUID(),vehicle,symptoms,codes,answer,createdAt:Date.now(),status:"Новая диагностика"},...v]);onNotify("Диагностика сохранена в истории");};
 const tab=(id:string,label:string)=><button className={"specialist-tab "+(mode===id?"active":"")} onClick={()=>{setMode(id);setAnswer("");setError("")}}>{label}</button>;
 return <section className="specialist-workspace">
  <div className="specialist-workspace-head"><div><div className="panel-kicker">{kind==="chef"?"РАБОЧАЯ КУХНЯ":"ТЕХНИЧЕСКИЙ ЦЕНТР"}</div><h2>{kind==="chef"?"Инструменты Шефа":"Инструменты Механика"}</h2><p>{kind==="chef"?"Рецепты, продукты, меню и организация мероприятий":"Диагностика, неисправности, ремонт и обслуживание"}</p></div></div>
  <div className="specialist-tabs">{kind==="chef"?<>{tab("home","Что приготовить")}{tab("pantry","Что есть дома")}{tab("recipe","Конкретный рецепт")}{tab("events","Праздник под ключ")}{tab("archive","Архив мероприятий")}</>:<>{tab("diagnosis","Диагностика")}{tab("repair","План ремонта")}{tab("maintenance","ТО и обслуживание")}{tab("history","История")}</>}</div>
  {kind==="chef"&&mode==="home"&&<div className="specialist-panel"><h3>Помощь Шефа</h3><p>Подберите блюдо, составьте меню или разберите кулинарную задачу.</p><div className="specialist-actions"><button onClick={()=>setMode("pantry")}>Приготовить из продуктов дома</button><button onClick={()=>setMode("recipe")}>Найти конкретный рецепт</button><button onClick={()=>setMode("events")}>Организовать праздник</button></div><label>Что хочется приготовить или узнать?<textarea value={dish} onChange={e=>setDish(e.target.value)} placeholder="Например: сытный ужин на 4 человек, без жарки"/></label><button className="hero-button" disabled={busy||!dish.trim()} onClick={()=>void ask(dish,"Ты — практичный ИИ-Шеф. Предложи подходящие блюда, точные ингредиенты, пошаговый рецепт, время приготовления и возможные замены.")}>{busy?"ГОТОВИМ ОТВЕТ…":"ПОДОБРАТЬ БЛЮДА"}</button></div>}
  {kind==="chef"&&mode==="pantry"&&<div className="specialist-panel"><h3>Что есть дома</h3><p>Перечислите продукты. Шеф предложит несколько вариантов, отметит чего не хватает и как заменить ингредиенты.</p><label>Имеющиеся продукты<textarea value={ingredients} onChange={e=>setIngredients(e.target.value)} placeholder="Курица, картофель, морковь, сметана, рис…"/></label><label>Пожелания<textarea value={dish} onChange={e=>setDish(e.target.value)} placeholder="На сколько человек, ограничения, время, способ приготовления…"/></label><button className="hero-button" disabled={busy||!ingredients.trim()} onClick={()=>void ask("Продукты дома: "+ingredients+"\nПожелания: "+dish,"Ты — ИИ-Шеф. Предложи 3-5 реальных блюд из перечисленных продуктов. Для каждого укажи чего не хватает, точные пропорции, пошаговый рецепт и время. Не придумывай наличие продуктов.")}>{busy?"ПОДБИРАЕМ…":"ПОДОБРАТЬ РЕЦЕПТЫ"}</button></div>}
  {kind==="chef"&&mode==="recipe"&&<div className="specialist-panel"><h3>Конкретное блюдо</h3><label>Название блюда<input value={dish} onChange={e=>setDish(e.target.value)} placeholder="Например: плов, борщ, сырники"/></label><label>Количество порций<input type="number" min="1" max="100" value={servings} onChange={e=>setServings(e.target.value)}/></label><label>Дополнительные пожелания<textarea value={ingredients} onChange={e=>setIngredients(e.target.value)} placeholder="Что учесть: продукты, техника, ограничения…"/></label><button className="hero-button" disabled={busy||!dish.trim()} onClick={()=>void ask("Блюдо: "+dish+"\nПорций: "+servings+"\nУсловия: "+ingredients,"Ты — профессиональный ИИ-Шеф. Дай точную рецептуру с граммовками на указанное число порций, подготовкой, температурой и временем, пошаговым приготовлением, заменами и аллергенами.")}>{busy?"СОСТАВЛЯЕМ…":"ПОЛУЧИТЬ РЕЦЕПТ"}</button></div>}
  {kind==="chef"&&mode==="events"&&<div className="specialist-panel"><h3>Праздник под ключ</h3><p>Создайте проект мероприятия. Он сохранится на этом устройстве; меню, гости, покупки и задачи можно редактировать.</p>{!current?<><label>Название мероприятия<input value={eventName} onChange={e=>setEventName(e.target.value)} placeholder="День рождения, свадьба, корпоратив…"/></label><label>Тип мероприятия<select value={eventType} onChange={e=>setEventType(e.target.value)}><option>День рождения</option><option>Свадьба</option><option>Юбилей</option><option>Детский праздник</option><option>Корпоратив</option><option>Новый год</option><option>Семейный праздник</option><option>Пикник / шашлыки</option><option>Фуршет</option><option>Другое</option></select></label><div className="specialist-form-grid"><label>Дата<input type="date" value={eventDate} onChange={e=>setEventDate(e.target.value)}/></label><label>Город<input value={eventCity} onChange={e=>setEventCity(e.target.value)} placeholder="Город"/></label><label>Бюджет<input type="number" min="0" value={eventBudget} onChange={e=>setEventBudget(e.target.value)} placeholder="Например, 50000 ₽"/></label><label>Взрослые<input type="number" min="0" max="500" value={eventAdults} onChange={e=>setEventAdults(e.target.value)}/></label><label>Дети<input type="number" min="0" max="500" value={eventChildren} onChange={e=>setEventChildren(e.target.value)}/></label></div><label>Уровень меню<select value={eventMenuLevel} onChange={e=>setEventMenuLevel(e.target.value)}><option value="economy">Экономный</option><option value="standard">Стандартный</option><option value="premium">Праздничный / премиум</option></select></label><label>Пожелания к меню<textarea value={eventWishes} onChange={e=>setEventWishes(e.target.value)} placeholder="Аллергии, ограничения, любимые блюда, без рыбы…"/></label><label className="specialist-check"><input type="checkbox" checked={eventBeverages} onChange={e=>setEventBeverages(e.target.checked)}/> Учесть напитки в меню</label><button className="hero-button" onClick={createEvent}>СОЗДАТЬ ПРОЕКТ</button><div className="specialist-actions"><button onClick={()=>setMode("archive")}>Открыть архив</button></div></>:<><div className="event-toolbar"><button onClick={()=>setSelected(null)}>← К проектам</button><b>{current.name}</b><button onClick={()=>{setEvents(v=>v.map(e=>e.id===current.id?{...e,archived:true}:e));setSelected(null);setMode("archive")}}>В архив</button></div><div className="specialist-form-grid"><label>Тип мероприятия<select value={current.type||"Другое"} onChange={e=>patchEvent({type:e.target.value})}><option>День рождения</option><option>Свадьба</option><option>Юбилей</option><option>Детский праздник</option><option>Корпоратив</option><option>Новый год</option><option>Семейный праздник</option><option>Пикник / шашлыки</option><option>Фуршет</option><option>Другое</option></select></label><label>Дата<input type="date" value={current.date} onChange={e=>patchEvent({date:e.target.value})}/></label><label>Город<input value={current.city} onChange={e=>patchEvent({city:e.target.value})} placeholder="Город"/></label><label>Бюджет, ₽<input type="number" min="0" value={current.budget} onChange={e=>patchEvent({budget:e.target.value})} placeholder="Бюджет"/></label><label>Взрослые<input type="number" min="0" max="500" value={current.adults??0} onChange={e=>patchEvent({adults:Math.max(0,Number(e.target.value)||0)})}/></label><label>Дети<input type="number" min="0" max="500" value={current.children??0} onChange={e=>patchEvent({children:Math.max(0,Number(e.target.value)||0)})}/></label></div><label>Уровень меню<select value={current.menuLevel||"standard"} onChange={e=>patchEvent({menuLevel:e.target.value})}><option value="economy">Экономный</option><option value="standard">Стандартный</option><option value="premium">Праздничный / премиум</option></select></label><label>Пожелания и ограничения<textarea value={current.wishes||""} onChange={e=>patchEvent({wishes:e.target.value})} placeholder="Аллергии, ограничения, любимые блюда…"/></label><label className="specialist-check"><input type="checkbox" checked={!!current.beverages} onChange={e=>patchEvent({beverages:e.target.checked})}/> Учесть напитки</label><div className="specialist-panel event-guests"><h3>Гости и приглашения</h3><p>Ведите список приглашённых и отмечайте ответы. Отказавшиеся и не пришедшие не входят в расчёт активных гостей.</p><div className="specialist-form-grid"><label>Имя / семья<input value={guestName} onChange={e=>setGuestName(e.target.value)} placeholder="Например, Иван Петров"/></label><label>Категория<select value={guestKind} onChange={e=>setGuestKind(e.target.value as "adult"|"child")}><option value="adult">Взрослый</option><option value="child">Ребёнок</option></select></label><label>Количество<input type="number" min="1" max="500" value={guestCount} onChange={e=>setGuestCount(e.target.value)}/></label><label>Примечание<input value={guestNote} onChange={e=>setGuestNote(e.target.value)} placeholder="Аллергия, предпочтения…"/></label></div><button className="outline-btn" onClick={addGuest}>ДОБАВИТЬ ГОСТЯ</button>{(current.guestList||[]).length===0?<p>Пока нет персонального списка гостей. Общее количество указано выше.</p>:(current.guestList||[]).map(g=><div className="event-list-row" key={g.id}><div><b>{g.name}</b><small>{g.kind==="child"?"Ребёнок":"Взрослый"} · {g.count} чел. {g.note?"· "+g.note:""}</small></div><select aria-label={"Статус гостя "+g.name} value={g.status} onChange={e=>updateGuest(g.id,{status:e.target.value as PlannerGuest["status"]})}><option value="invited">Приглашён</option><option value="confirmed">Подтвердил</option><option value="declined">Отказался</option><option value="no_show">Не пришёл</option></select><button onClick={()=>removeGuest(g.id)} aria-label={"Удалить гостя "+g.name}>УДАЛИТЬ</button></div>)}<p><b>Учтённые гости:</b> {guestTotals(current.guestList||[]).adult} взрослых · {guestTotals(current.guestList||[]).child} детей</p></div><label>Моё меню<textarea value={current.menu} onChange={e=>patchEvent({menu:e.target.value})} placeholder="Блюда, напитки и выбранные позиции…"/></label><label>Список покупок<textarea value={current.shopping} onChange={e=>patchEvent({shopping:e.target.value})} placeholder="Продукты и количества…"/></label><label>Подготовка и задачи<textarea value={current.tasks} onChange={e=>patchEvent({tasks:e.target.value})} placeholder="Купить, приготовить, украсить, подтвердить гостей…"/></label><button className="outline-btn" onClick={()=>void ask("Мероприятие: "+current.name+". Тип: "+(current.type||"не указан")+". Город: "+current.city+". Дата: "+current.date+". Бюджет: "+current.budget+" ₽. Взрослые: "+(current.adults??0)+". Дети: "+(current.children??0)+". Уровень меню: "+(current.menuLevel||"standard")+". Напитки: "+(current.beverages?"учесть":"не включать")+". Пожелания: "+(current.wishes||"не указаны")+". Уже выбранное меню: "+current.menu,"Ты — профессиональный организатор мероприятий и ИИ-Шеф. Составь меню по указанному уровню и бюджету, раздели блюда на закуски, салаты, горячее, гарниры и десерты; учти взрослых и детей отдельно, укажи ориентировочные порции и точные количества продуктов в граммах/миллилитрах/штуках, сгруппируй общий список покупок, выдели допущения и не выдумывай рыночные цены. Если бюджет не позволяет меню, предложи экономию. Учитывай пожелания и аллергенные ограничения.")}>СОСТАВИТЬ МЕНЮ И РАСЧЁТ ПРОДУКТОВ</button></>}</div>}
  {kind==="chef"&&mode==="archive"&&<div className="specialist-panel"><h3>Архив мероприятий</h3>{events.filter(e=>e.archived).length===0?<p>Архив пуст. Завершённые проекты будут храниться здесь.</p>:events.filter(e=>e.archived).map(e=><div className="event-list-row" key={e.id}><button onClick={()=>{setSelected(e.id);setMode("events")}}>{e.name}<small>{e.date||"Дата не указана"} · {e.city||"Город не указан"}</small></button><button onClick={()=>setEvents(v=>v.map(x=>x.id===e.id?{...x,archived:false}:x))}>Восстановить</button><button onClick={()=>setEvents(v=>v.filter(x=>x.id!==e.id))}>Удалить</button></div>)}</div>}
  {kind==="chef"&&mode==="events"&&!current&&events.filter(e=>!e.archived).length>0&&<div className="specialist-panel"><h3>Мои мероприятия</h3>{events.filter(e=>!e.archived).map(e=><div className="event-list-row" key={e.id}><button onClick={()=>setSelected(e.id)}>{e.name}<small>{e.date||"Дата не указана"} · {e.city||"Город не указан"}</small></button><button onClick={()=>setEvents(v=>v.map(x=>x.id===e.id?{...x,archived:true}:x))}>В архив</button></div>)}</div>}
  {kind==="mechanic"&&mode==="diagnosis"&&<div className="specialist-panel"><h3>Диагностика автомобиля или техники</h3><label>Марка, модель, год, двигатель<input value={vehicle} onChange={e=>setVehicle(e.target.value)} placeholder="Например: Toyota Corolla 2012, 1.6 бензин"/></label><label>Симптомы<textarea value={symptoms} onChange={e=>setSymptoms(e.target.value)} placeholder="Когда проявляется неисправность, звуки, запахи, поведение…"/></label><label>Коды ошибок<textarea value={codes} onChange={e=>setCodes(e.target.value)} placeholder="Например: P0301, P0420 или «не считывал»"/></label><button className="hero-button" disabled={busy||!vehicle.trim()||!symptoms.trim()} onClick={()=>void ask("Техника: "+vehicle+"\nСимптомы: "+symptoms+"\nКоды: "+codes,"Ты — технический ИИ-Механик. Проведи структурированную диагностику: уточняющие вопросы, вероятные причины по приоритету, безопасные первичные проверки, необходимые инструменты и когда прекратить эксплуатацию и обратиться в сервис. Не выдавай предположение за диагноз.")}>ПРОВЕСТИ ДИАГНОСТИКУ</button><button className="outline-btn" onClick={saveCase}>СОХРАНИТЬ В ИСТОРИЮ</button></div>}
  {kind==="mechanic"&&mode==="repair"&&<div className="specialist-panel"><h3>План ремонта</h3><label>Техника<input value={vehicle} onChange={e=>setVehicle(e.target.value)} placeholder="Марка, модель, год, агрегат"/></label><label>Неисправность и уже выполненные проверки<textarea value={symptoms} onChange={e=>setSymptoms(e.target.value)} placeholder="Опишите проблему и результаты проверки"/></label><button className="hero-button" disabled={busy||!vehicle.trim()||!symptoms.trim()} onClick={()=>void ask("Техника: "+vehicle+"\nПроблема: "+symptoms+"\nКоды: "+codes,"Ты — ИИ-Механик. Составь план ремонта: последовательность проверок и работ, инструменты, расходники, возможные детали, риски и критерии успешного ремонта. Не выдумывай точные номера деталей без VIN/комплектации.")}>СОСТАВИТЬ ПЛАН РЕМОНТА</button></div>}
  {kind==="mechanic"&&mode==="maintenance"&&<div className="specialist-panel"><h3>ТО и обслуживание</h3><label>Автомобиль / техника<input value={vehicle} onChange={e=>setVehicle(e.target.value)} placeholder="Марка, модель, год, двигатель"/></label><label>Пробег и история обслуживания<textarea value={symptoms} onChange={e=>setSymptoms(e.target.value)} placeholder="Текущий пробег, когда меняли масло, фильтры, ремни…"/></label><button className="hero-button" disabled={busy||!vehicle.trim()} onClick={()=>void ask("Техника: "+vehicle+"\nПробег и история: "+symptoms,"Ты — ИИ-Механик. Составь план регламентного обслуживания с интервалами по времени и пробегу. Укажи, какие данные нужно сверить с руководством производителя; не придумывай регламент конкретной модификации.")}>СОСТАВИТЬ ПЛАН ТО</button></div>}
  {kind==="mechanic"&&mode==="history"&&<div className="specialist-panel"><h3>История обращений</h3>{cases.length===0?<p>Сохранённых диагностик пока нет.</p>:cases.map(c=><div className="event-list-row" key={c.id}><button onClick={()=>{setVehicle(c.vehicle);setSymptoms(c.symptoms);setCodes(c.codes);setAnswer(c.answer);setMode("diagnosis")}}>{c.vehicle}<small>{new Date(c.createdAt).toLocaleString("ru-RU")} · {c.status}</small></button><button onClick={()=>setCases(v=>v.filter(x=>x.id!==c.id))}>Удалить</button></div>)}</div>}
  {busy&&<div className="specialist-result">ШЕФ СОСТАВЛЯЕТ ОТВЕТ…</div>}{error&&<div className="specialist-error" role="alert">{error}</div>}{answer&&<div className="specialist-result"><div className="panel-kicker">РЕЗУЛЬТАТ АНАЛИЗА</div><div className="specialist-answer">{answer}</div><button className="outline-btn" onClick={()=>{navigator.clipboard?.writeText(answer);onNotify("Ответ скопирован")}}>СКОПИРОВАТЬ ОТВЕТ</button></div>}
  <small className="specialist-storage-note">Локальные проекты и история сохраняются на этом устройстве. Облачная синхронизация и перенос старых записей ещё требуют отдельной миграции.</small>
 </section>
}

function App(){
 const tab=useSoyuzStore(state=>state.tab);
 const setTab=useSoyuzStore(state=>state.setTab);
 const [active,setActive]=useState<Helper|null>(null);
  const [workspace,setWorkspace]=useState<"chef"|"mechanic"|null>(null);
 const [sessionUser,setSessionUser]=useState<SessionUser|null>(null);
 const [authReady,setAuthReady]=useState(false);
 const [serverHealth,setServerHealth]=useState<"checking"|"online"|"offline">("checking");
 const [hapticsEnabled,setHapticsEnabled]=useState(()=>localStorage.getItem("soyuz_haptics")!=="false");
 const [motionEnabled,setMotionEnabled]=useState(()=>localStorage.getItem("soyuz_motion")!=="false");
 useEffect(()=>{apiFetch("/health",{cache:"no-store"}).then(r=>setServerHealth(r.ok?"online":"offline")).catch(()=>setServerHealth("offline"));},[]);
 useEffect(()=>{document.documentElement.classList.toggle("motion-disabled",!motionEnabled);},[motionEnabled]);
 useEffect(()=>{const token=localStorage.getItem("ai_bragina_token");if(!token){setAuthReady(true);return;}apiFetch("/auth/me",{headers:{Authorization:"Bearer "+token},cache:"no-store"}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok||!d.user)throw new Error("session");setSessionUser(d.user);localStorage.setItem("ai_bragina_user",JSON.stringify(d.user));}).catch(()=>{localStorage.removeItem("ai_bragina_token");localStorage.removeItem("ai_bragina_user");}).finally(()=>setAuthReady(true));},[]);
 const handleAuth=(user:SessionUser)=>{setSessionUser(user);};
 const logout=async()=>{const token=localStorage.getItem("ai_bragina_token");try{if(token)await apiFetch("/auth/logout",{method:"POST",headers:{Authorization:"Bearer "+token}})}catch{}localStorage.removeItem("ai_bragina_token");localStorage.removeItem("ai_bragina_user");setSessionUser(null);setTab("home");setActive(null);};
 const [query,setQuery]=useState("");
 const [chat,setChat]=useState("");
 const [assistantLog,setAssistantLog]=useState<Array<{role:"user"|"assistant";content:string}>>([]);
 const [aiBusy,setAiBusy]=useState(false);
 const [toast,setToast]=useState("");
 const [profile,setProfile]=useState(()=>{try{return JSON.parse(localStorage.getItem("soyuz_personal_dossier")||"{}")}catch{return {}}});
 const [tasks,setTasks]=useState<Array<{id?:number;serverId?:string;title:string;completed:boolean;createdAt:number}>>([]);
 const [newTask,setNewTask]=useState("");
 useEffect(()=>{let alive=true;soyuzDb.tasks.orderBy("createdAt").reverse().toArray().then(items=>{if(alive)setTasks(items)}).catch(()=>undefined);return()=>{alive=false}},[]);
 useEffect(()=>{if(!sessionUser)return;let alive=true;const sync=async()=>{try{const token=localStorage.getItem("ai_bragina_token")||"";const local=await soyuzDb.tasks.orderBy("createdAt").reverse().toArray();const r=await apiFetch("/tasks",{headers:{Authorization:"Bearer "+token},cache:"no-store"});if(!r.ok)return;const d=await r.json();const server=d.tasks||[];const merged:Array<{id?:number;serverId?:string;title:string;completed:boolean;createdAt:number}>=[];
 const localByServerId=new Map(local.filter(item=>item.serverId).map(item=>[item.serverId!,item]));
 for(const item of server){const existing=localByServerId.get(item.id);if(existing){merged.push({...existing,title:item.title,completed:!!item.completed});}else{const record={serverId:item.id,title:item.title,completed:!!item.completed,createdAt:Date.parse(item.created_at)||Date.now()};const id=await soyuzDb.tasks.add(record);merged.push({...record,id});}}
 for(const item of local.filter(x=>!x.serverId)){try{const created=await apiFetch("/tasks",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({action:"create",title:item.title})});const result=await created.json();if(created.ok&&result.task){await soyuzDb.tasks.update(item.id!,{serverId:result.task.id});merged.push({...item,serverId:result.task.id});}else merged.push(item);}catch{merged.push(item);}}
 for(const item of local.filter(x=>x.serverId&&!server.some((x:any)=>x.id===item.serverId)))merged.push(item);
 if(alive)setTasks(merged.sort((a,b)=>b.createdAt-a.createdAt));
 }catch{}};
 void sync();return()=>{alive=false}},[sessionUser?.id]);

 const addTask=async()=>{const title=newTask.trim();if(!title)return;const item={title,completed:false,createdAt:Date.now()};const id=await soyuzDb.tasks.add(item);let saved:{id:number;serverId?:string;title:string;completed:boolean;createdAt:number}={...item,id};try{const token=localStorage.getItem("ai_bragina_token")||"";const r=await apiFetch("/tasks",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({action:"create",title})});const d=await r.json();if(r.ok&&d.task){saved={...saved,serverId:d.task.id};await soyuzDb.tasks.update(id,{serverId:d.task.id});}}catch{}setTasks(v=>[saved,...v]);setNewTask("");};
 const toggleTask=async(id:number,completed:boolean)=>{const task=tasks.find(t=>t.id===id);await soyuzDb.tasks.update(id,{completed:!completed});setTasks(v=>v.map(t=>t.id===id?{...t,completed:!completed}:t));if(task?.serverId){const token=localStorage.getItem("ai_bragina_token")||"";void apiFetch("/tasks",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({action:"update",id:task.serverId,title:task.title,completed:!completed})}).catch(()=>undefined);}};
 const removeTask=async(id:number)=>{const task=tasks.find(t=>t.id===id);if(task?.serverId){const token=localStorage.getItem("ai_bragina_token")||"";try{await apiFetch("/tasks",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({action:"delete",id:task.serverId})});}catch{}}await soyuzDb.tasks.delete(id);setTasks(v=>v.filter(t=>t.id!==id));};
 useEffect(()=>{let alive=true;soyuzDb.profiles.get("current").then(saved=>{if(alive&&saved)setProfile({firstName:saved.firstName,lastName:saved.lastName,displayName:saved.displayName,about:saved.about})}).catch(()=>undefined);return()=>{alive=false}},[]);
 useEffect(()=>{const record={id:"current" as const,firstName:profile.firstName||"",lastName:profile.lastName||"",displayName:profile.displayName||"",about:profile.about||"",updatedAt:Date.now()};soyuzDb.profiles.put(record).catch(()=>undefined)},[profile]);
 useEffect(()=>{const token=localStorage.getItem("ai_bragina_token");if(!sessionUser||!token)return;let live=true;apiFetch("/profile",{headers:{Authorization:"Bearer "+token},cache:"no-store"}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||"profile");if(live&&d.profile)setProfile((p:any)=>({...p,firstName:d.profile.first_name||p.firstName||"",lastName:d.profile.last_name||p.lastName||"",displayName:d.profile.display_name||p.displayName||sessionUser.display_name,about:d.profile.about||p.about||""}));}).catch(()=>undefined);return()=>{live=false}},[sessionUser?.id]);
 const saveProfile=async()=>{const token=localStorage.getItem("ai_bragina_token")||"";const payload={first_name:profile.firstName||"",last_name:profile.lastName||"",display_name:profile.displayName||sessionUser?.display_name||"",about:profile.about||""};localStorage.setItem("soyuz_personal_dossier",JSON.stringify(profile));await soyuzDb.profiles.put({id:"current",firstName:payload.first_name,lastName:payload.last_name,displayName:payload.display_name,about:payload.about,updatedAt:Date.now()});try{const r=await apiFetch("/profile",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||"Не удалось синхронизировать профиль");setSessionUser((u:any)=>u?({...u,display_name:d.profile.display_name}):u);notify("Личное дело сохранено в аккаунте и синхронизировано");}catch(e){notify("Сохранено на устройстве. Серверная синхронизация не удалась: "+(e instanceof Error?e.message:"ошибка"));}};

 const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(""),2400)};
 const go=(t:string)=>{setTab(t);setActive(null);setWorkspace(null);if(hapticsEnabled)void Haptics.impact({style:ImpactStyle.Light}).catch(()=>undefined);window.scrollTo({top:0,behavior:"smooth"});};
 const openHelper=(h:Helper)=>{setActive(h);setWorkspace(null);setChat("");setAssistantLog([]);setAiBusy(false);};
 const visibleHelpers=helpers.filter(h=>(h.name+" "+h.role+" "+h.desc).toLowerCase().includes(query.toLowerCase()));
 const nav=[{id:"home",label:"ГЛАВНАЯ",icon:Home},{id:"helpers",label:"БЮРО",icon:Sparkles},{id:"community",label:"СООБЩЕСТВО",icon:Users},{id:"messages",label:"СВЯЗЬ",icon:MessageCircle},{id:"work",label:"ДЕЛА",icon:ClipboardList},{id:"profile",label:"ЛИЧНОЕ ДЕЛО",icon:UserRound}];
 const systemDate=new Date().toLocaleDateString("ru-RU",{day:"2-digit",month:"long",year:"numeric"}).toUpperCase();
 const send=async()=>{const prompt=chat.trim();if(!prompt||!active||aiBusy)return;setChat("");setAssistantLog(v=>[...v,{role:"user",content:prompt}]);setAiBusy(true);try{const system="Ты — "+active.name+" («СОЮЗ»), специализированный цифровой помощник по направлению: "+active.role+". "+active.desc+"\nТвои компетенции: "+active.skills.join("; ")+". Отвечай на русском языке, структурированно и практично. Сначала уточняй критически важные недостающие данные. Не выдумывай факты, цены, законы или диагнозы. В вопросах здоровья не ставь диагноз и рекомендуй врача при тревожных симптомах. В правовых вопросах отмечай юрисдикцию и дату актуальности. Давай безопасные пошаговые рекомендации.";const response=await apiFetch("/",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+(localStorage.getItem("ai_bragina_token")||"")},body:JSON.stringify({model:"openai/gpt-oss-120b",messages:[{role:"system",content:system},...assistantLog.slice(-8),{role:"user",content:prompt}],temperature:0.35,max_tokens:1600})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error?.message||data.error||"Сервис ИИ временно недоступен");const answer=data.choices?.[0]?.message?.content;if(!answer)throw new Error("ИИ вернул пустой ответ");setAssistantLog(v=>[...v,{role:"assistant",content:answer}]);if(data.usage)void apiFetch("/usage",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+(localStorage.getItem("ai_bragina_token")||"")},body:JSON.stringify({usage:data.usage,model:"openai/gpt-oss-120b",page:"helper-"+active.id})}).catch(()=>undefined);}catch(e){setAssistantLog(v=>[...v,{role:"assistant",content:e instanceof Error?e.message:"Не удалось получить ответ. Попробуйте позже."}]);}finally{setAiBusy(false);}};
 if(!authReady)return <div className="auth-loading"><span className="live-dot"/> ПОДКЛЮЧЕНИЕ К СОЮЗУ…</div>;
 if(!sessionUser)return <AuthScreen onAuth={handleAuth}/>;
 return <div className="union-app">
  <div className="grain"/>
  <header className="union-header">
   <button className="seal" onClick={()=>go("home")} aria-label="На главную"><span className="seal-star">✦</span><span className="seal-orbit"/></button>
   <div className="brand-lockup"><div className="brand-name">СОЮЗ<span>®</span></div><div className="brand-sub">ЕДИНАЯ ЦИФРОВАЯ СИСТЕМА</div></div>
   <div className="header-center"><span className="live-dot"/> СИСТЕМА АКТИВНА <b>·</b> {systemDate}</div>
   <div className="header-actions"><button className="round-icon" onClick={()=>notify("Новых оповещений пока нет")}><Bell size={18}/><i/></button><button className="profile-chip" onClick={()=>go("profile")}><span className="profile-avatar">{(sessionUser.display_name||sessionUser.username||"С").slice(0,1).toUpperCase()}</span><span>{(sessionUser.display_name||sessionUser.username||"УЧАСТНИК").toUpperCase()}</span></button></div>
  </header>
  <div className="mobile-status"><span className="live-dot"/> СИСТЕМА АКТИВНА <span>·</span> {systemDate}</div>
  <div className="union-layout">
   <aside className="side-rail">
    <div className="rail-label">НАВИГАЦИЯ</div>
    {nav.map(n=><button key={n.id} className={"rail-link "+(tab===n.id&&!active?"selected":"")} onClick={()=>go(n.id)}><n.icon size={18}/><span>{n.label}</span>{n.id==="messages"&&<i className="rail-count">2</i>}</button>)}
    <div className="rail-rule"/>
    <div className="rail-label">РАЗДЕЛЫ СИСТЕМЫ</div>
    <button className="rail-link" onClick={()=>go("helpers")}><ChefHat size={18}/><span>БЮРО ИНТЕЛЛЕКТА</span></button>
    <button className="rail-link" onClick={()=>go("work")}><CalendarDays size={18}/><span>ПЛАНИРОВАНИЕ</span></button><button className={"rail-link "+(tab==="video"?"selected":"")} onClick={()=>go("video")}><Play size={18}/><span>ВИДЕОЛЕНТА</span></button>
    <button className={"rail-link "+(tab==="archive"?"selected":"")} onClick={()=>go("archive")}><Archive size={18}/><span>АРХИВ</span></button>
    <button className={"rail-link "+(tab==="signals"?"selected":"")} onClick={()=>go("signals")}><Bell size={18}/><span>СИГНАЛЫ</span></button>
    <button className={"rail-link "+(tab==="profile"?"selected":"")} onClick={()=>go("profile")}><UserRound size={18}/><span>ЛИЧНОЕ ДЕЛО</span></button>
    <button className={"rail-link "+(tab==="settings"?"selected":"")} onClick={()=>go("settings")}><Settings size={18}/><span>ПАРАМЕТРЫ СИСТЕМЫ</span></button>
    <div className="rail-bottom"><div className="rail-stamp">С</div><div><b>СОЮЗ / 01</b><small>ВЕРСИЯ {APP_VERSION} · ПРЕДПРОСМОТР</small></div></div>
   </aside>
   <main className="main-stage">
    <AnimatePresence mode="wait">
    {active ? <motion.section key="detail" className="helper-detail" initial={{opacity:0,y:14}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}}>
      <button className="back-link" onClick={()=>setActive(null)}>← К БЮРО ИНТЕЛЛЕКТА</button>
      <div className="detail-hero">
       <div className="detail-copy"><div className="eyebrow"><span className="live-dot"/> ПЕРСОНАЛЬНЫЙ ЦИФРОВОЙ СПЕЦИАЛИСТ</div><h1>{active.name}</h1><p>{active.desc}</p><div className="detail-status"><span className={active.status==="open"?"status-open":"status-locked"}>{active.status==="open"?"● ДОСТУПЕН ДЛЯ РАБОТЫ":"▣ ГОТОВИТСЯ К ЗАПУСКУ"}</span><span>ОТДЕЛ: {active.role.toUpperCase()}</span></div>
        {(active.id==="chef"||active.id==="mechanic")&&<button className="hero-button" onClick={()=>setWorkspace(active.id as "chef"|"mechanic")}>{active.id==="chef"?"ОТКРЫТЬ ИНСТРУМЕНТЫ ШЕФА":"ОТКРЫТЬ ИНСТРУМЕНТЫ МЕХАНИКА"} <ArrowRight size={16}/></button>}</div>
       <div className={"detail-mascot-panel "+active.color}><div className="orbit orbit-a"/><div className="orbit orbit-b"/><Mascot kind={active.icon}/><div className="mascot-caption">СПЕЦИАЛИСТ СОЮЗА №{String(helpers.indexOf(active)+1).padStart(2,"0")}</div></div>
      </div>
      {workspace&&<SpecialistWorkspace kind={workspace} onNotify={notify}/>}
      {!workspace&&<div className="detail-grid">
       <section className="paper-panel"><div className="panel-kicker">01 / КОМПЕТЕНЦИИ</div><h2>Чем поможет специалист</h2><div className="skill-list">{active.skills.map((s,i)=><div className="skill-row"><span>{String(i+1).padStart(2,"0")}</span><b>{s}</b><Check size={16}/></div>)}</div></section>
       <section className="paper-panel usage-panel"><div className="panel-kicker">02 / РАБОЧЕЕ МЕСТО</div><h2>Поставить задачу</h2>{active.status==="open"?<><div className="chat-intro">Опишите ситуацию обычными словами. Специалист уточнит детали и предложит план действий.</div><div className="sample-prompt" onClick={()=>setChat(active.sample)}><Sparkles size={15}/><span>{active.sample}</span><ArrowRight size={15}/></div><div className="mini-chat">{assistantLog.map((m,i)=><div className={"mini-bubble "+(m.role==="user"?"mine":"bot")} key={i}>{m.content}</div>)}{aiBusy&&<div className="mini-bubble bot ai-thinking">СОЮЗ АНАЛИЗИРУЕТ ЗАДАЧУ…</div>}</div><div className="task-input"><input value={chat} onChange={e=>setChat(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()} placeholder="Напишите задачу..."/><button onClick={()=>void send()} disabled={aiBusy||!chat.trim()}><Send size={17}/></button></div><small className="demo-note">ИИ-ПОМОЩНИК · ЗАПРОСЫ ОТПРАВЛЯЮТСЯ ЧЕРЕЗ ЗАЩИЩЁННЫЙ СЕРВЕР</small></>:<div className="locked-detail"><div className="lock-emblem"><LockKeyhole size={25}/></div><h3>Специалист проходит подготовку</h3><p>Мы разрабатываем инструменты, проверяем качество рекомендаций и готовим подключение к рабочим данным.</p><button className="notify-btn" onClick={()=>notify("Отметили интерес к помощнику "+active.name)}>Сообщить о запуске <Bell size={15}/></button></div>}</section>
      </div>}
    </motion.section> :
    tab==="home" ? <motion.div key="home" className="home-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}}>
     <div className="hero-banner">
      <div className="hero-grid"/>
      <div className="hero-content"><div className="eyebrow"><span className="live-dot"/> ЕДИНАЯ ЦИФРОВАЯ СИСТЕМА · 2026</div><h1>ОДНА СИСТЕМА.<br/><em>ТЫСЯЧИ ВОЗМОЖНОСТЕЙ.</em></h1><p>Общение, знания, работа и интеллектуальные помощники — в едином цифровом пространстве.</p><button className="hero-button" onClick={()=>go("helpers")}>ОТКРЫТЬ БЮРО ИНТЕЛЛЕКТА <ArrowRight size={16}/></button></div>
      <div className="hero-art"><div className="hero-sun"/><div className="hero-ring r1"/><div className="hero-ring r2"/><div className="hero-monument"><div className="monument-star">✦</div><div className="monument-pillar p1"/><div className="monument-pillar p2"/><div className="monument-pillar p3"/><div className="monument-base"/></div><div className="hero-art-label">ПРОЕКТ<br/>БУДУЩЕГО</div></div>
      <div className="hero-index">СОЮЗ / 001</div>
     </div>
     <div className="ticker"><span>✦</span> ЗНАНИЯ <i/> ВОЗМОЖНОСТИ <i/> ВЗАИМОПОМОЩЬ <i/> СОЗИДАНИЕ <i/> БУДУЩЕЕ <i/> <span>✦</span> ЗНАНИЯ <i/> ВОЗМОЖНОСТИ</div>
     <div className="section-head"><div><div className="eyebrow">ЦЕНТР СОЮЗА</div><h2>ВАШЕ ПРОСТРАНСТВО</h2></div><button className="text-link" onClick={()=>go("helpers")}>ВСЕ СЛУЖБЫ <ArrowRight size={15}/></button></div>
     <div className="dashboard-grid">
      <button className="dash-card dispatch" onClick={()=>go("work")}><div className="dash-icon"><CalendarDays/></div><div><small>ПЛАНИРОВАНИЕ</small><h3>Мои задачи</h3><p>Планируйте день и держите важное под контролем.</p></div><span className="dash-arrow"><ArrowRight/></span><b className="card-index">01</b></button>
      <button className="dash-card comms" onClick={()=>go("messages")}><div className="dash-icon"><MessageCircle/></div><div><small>СИСТЕМА СВЯЗИ</small><h3>Личные сообщения</h3><p>Личные диалоги, общие чаты, аудио- и видеосвязь.</p></div><span className="dash-arrow"><ArrowRight/></span><b className="card-index">02</b></button>
      <button className="dash-card people-card" onClick={()=>go("community")}><div className="dash-icon"><Users/></div><div><small>СООБЩЕСТВО СОЮЗА</small><h3>Сообщество</h3><p>Лента событий, люди и общие интересы.</p></div><span className="dash-arrow"><ArrowRight/></span><b className="card-index">03</b></button><button className="dash-card video-dash" onClick={()=>go("video")}><div className="dash-icon"><Play/></div><div><small>МЕДИАПРОСТРАНСТВО</small><h3>Видеолента</h3><p>Короткие ролики по интересующим темам.</p></div><span className="dash-arrow"><ArrowRight/></span><b className="card-index">04</b></button>
     </div>
     <div className="section-head helper-section-head"><div><div className="eyebrow">ИНТЕЛЛЕКТУАЛЬНЫЕ СЛУЖБЫ</div><h2>ВАШИ БЮРО</h2></div><button className="text-link" onClick={()=>go("helpers")}>ВЕСЬ СОСТАВ <ArrowRight size={15}/></button></div>
     <div className="helper-grid">{helpers.slice(0,3).map(h=><HelperCard key={h.id} h={h} onClick={()=>openHelper(h)}/>)}</div>
     <div className="bottom-motto"><span>✦</span><div>СОЗДАНО ДЛЯ ЛЮДЕЙ.<br/><b>РАБОТАЕТ ДЛЯ БУДУЩЕГО.</b></div><small>СОЮЗ · ЦИФРОВАЯ ЭКОСИСТЕМА</small></div>
    </motion.div> :
    tab==="video" ? <motion.div key="video" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}}><VideoView/></motion.div> :
    tab==="helpers" ? <motion.div key="helpers" className="catalog-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}}>
      <div className="page-title-row"><div><div className="eyebrow">СОСТАВ БЮРО · 07 СПЕЦИАЛИСТОВ</div><h1>БЮРО ИНТЕЛЛЕКТА</h1><p>Каждый специалист — отдельный инструмент для конкретной задачи.</p></div><div className="catalog-seal">С<span>✦</span></div></div>
      <label className="catalog-search"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Найти специалиста или направление..."/></label>
      <div className="helper-grid catalog-grid">{visibleHelpers.map(h=><HelperCard key={h.id} h={h} onClick={()=>openHelper(h)}/>)}</div>
      <div className="catalog-foot"><ShieldCheck size={18}/> Состав бюро расширяется. Новые специалисты проходят проверку перед запуском.</div>
    </motion.div> :
    tab==="archive" ? <motion.div key="archive" className="generic-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">ЛИЧНОЕ ХРАНИЛИЩЕ</div><h1>АРХИВ ДЕЛ</h1><p className="lead">Завершённые задачи, сохранённые на этом устройстве.</p><div className="task-board"><div className="task-board-head"><b>ЗАВЕРШЁННЫЕ ЗАДАЧИ</b><span>{tasks.filter(t=>t.completed).length} В АРХИВЕ</span></div>{tasks.filter(t=>t.completed).length===0?<div className="task-empty"><Archive size={26}/><b>Архив пока пуст</b><span>Завершённые задачи появятся здесь</span></div>:tasks.filter(t=>t.completed).map(t=><div className="task-row is-done" key={t.id}><button className="task-check" onClick={()=>t.id!==undefined&&void toggleTask(t.id,true)} aria-label="Вернуть в дела"><Check size={16}/></button><span>{t.title}</span><button className="task-delete" onClick={()=>t.id!==undefined&&void removeTask(t.id)} aria-label="Удалить">×</button></div>)}</div></motion.div> :
    tab==="signals" ? <motion.div key="signals" className="generic-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">ЦЕНТР УВЕДОМЛЕНИЙ</div><h1>СИГНАЛЫ СИСТЕМЫ</h1><p className="lead">Состояние подключённых компонентов и важные события аккаунта.</p><div className="signal-list"><div className="signal-row"><span className={serverHealth==="online"?"signal-state good":"signal-state"}>{serverHealth==="online"?"●":"○"}</span><div><b>Сервер СОЮЗ</b><small>{serverHealth==="checking"?"Проверяем соединение…":serverHealth==="online"?"Сервер отвечает, API доступно":"Нет ответа от сервера"}</small></div><button onClick={()=>{setServerHealth("checking");apiFetch("/health",{cache:"no-store"}).then(r=>setServerHealth(r.ok?"online":"offline")).catch(()=>setServerHealth("offline"));}}>ПРОВЕРИТЬ</button></div><div className="signal-row"><span className="signal-state good">●</span><div><b>Локальное хранилище</b><small>Список дел и профиль поддерживают сохранение на устройстве</small></div></div><div className="signal-row"><span className="signal-state good">●</span><div><b>Учётная запись</b><small>Вы вошли как @{sessionUser.username}</small></div></div></div></motion.div> :
    tab==="settings" ? <motion.div key="settings" className="generic-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">ПЕРСОНАЛЬНАЯ КОНФИГУРАЦИЯ</div><h1>ПАРАМЕТРЫ СИСТЕМЫ</h1><p className="lead">Настройки интерфейса и отклика устройства.</p><div className="settings-list"><label className="setting-row"><span><b>Плавные анимации</b><small>Переходы и движения интерфейса</small></span><input type="checkbox" checked={motionEnabled} onChange={e=>{setMotionEnabled(e.target.checked);localStorage.setItem("soyuz_motion",String(e.target.checked));document.documentElement.classList.toggle("motion-disabled",!e.target.checked);}}/></label><label className="setting-row"><span><b>Тактильный отклик</b><small>Лёгкая вибрация при навигации на поддерживаемых устройствах</small></span><input type="checkbox" checked={hapticsEnabled} onChange={e=>{setHapticsEnabled(e.target.checked);localStorage.setItem("soyuz_haptics",String(e.target.checked));}}/></label><div className="setting-row"><span><b>Тема оформления</b><small>Технологическая тёмная тема СОЮЗ</small></span><span className="setting-value">АКТИВНА</span></div><div className="setting-row"><span><b>Учётная запись</b><small>@{sessionUser.username}</small></span><button className="outline-btn" onClick={()=>go("profile")}>ЛИЧНОЕ ДЕЛО</button></div></div></motion.div> :
    tab==="profile" ? <motion.div key="profile" className="generic-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">УЧЁТНАЯ ЗАПИСЬ УЧАСТНИКА</div><h1>ЛИЧНОЕ ДЕЛО</h1><p className="lead">Ваша личная карточка в системе СОЮЗ.</p><div className="paper-panel dossier-panel"><div className="post-emblem">С</div><h2>Создать личное дело</h2><p>Заполните основные сведения. Данные личного дела сохраняются в вашем аккаунте и синхронизируются с сервером.</p><label className="dossier-field">Имя<input value={profile.firstName||""} onChange={e=>setProfile({...profile,firstName:e.target.value})} placeholder="Введите имя"/></label><label className="dossier-field">Фамилия<input value={profile.lastName||""} onChange={e=>setProfile({...profile,lastName:e.target.value})} placeholder="Введите фамилию"/></label><label className="dossier-field">Отображаемое имя<input value={profile.displayName||""} onChange={e=>setProfile({...profile,displayName:e.target.value})} placeholder="Как вас будут видеть участники"/></label><label className="dossier-field">О себе<textarea value={profile.about||""} onChange={e=>setProfile({...profile,about:e.target.value})} placeholder="Кратко расскажите о себе"/></label><button className="hero-button" onClick={()=>void saveProfile()}>СОХРАНИТЬ ЛИЧНОЕ ДЕЛО <Check size={16}/></button><small className="demo-note">АККАУНТ: @{sessionUser.username} · ПРОФИЛЬ СИНХРОНИЗИРУЕТСЯ С СЕРВЕРОМ</small><div className="app-version"><b>СОЮЗ</b> · версия {APP_VERSION}<br/><span>Сборка: {APP_BUILD}</span></div><button className="auth-switch profile-logout" onClick={()=>void logout()}>ВЫЙТИ ИЗ АККАУНТА</button></div></motion.div> :
    tab==="community" ? <motion.div key="community" className="generic-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">СООБЩЕСТВО СОЮЗА · ПУБЛИКАЦИИ УЧАСТНИКОВ</div><h1>СООБЩЕСТВО</h1><p className="lead">Публикуйте идеи, общайтесь и поддерживайте друг друга.</p><CommunityView token={localStorage.getItem("ai_bragina_token")||""} user={sessionUser}/></motion.div> :
    tab==="messages" ? <motion.div key="messages" className="generic-page messages-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">СИСТЕМА СВЯЗИ · СЕРВЕРНЫЕ ДИАЛОГИ</div><h1>СВЯЗЬ</h1><p className="lead">Личные диалоги с участниками СОЮЗ. Сообщения сохраняются на сервере и доступны после повторного входа.</p><MessagesView token={localStorage.getItem("ai_bragina_token")||""} user={sessionUser}/></motion.div> :
    <motion.div key="work" className="generic-page" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}}><div className="eyebrow">ПЛАНИРОВАНИЕ · ЛОКАЛЬНОЕ ХРАНИЛИЩЕ</div><h1>МОИ ДЕЛА</h1><p className="lead">Создавайте задачи и отмечайте выполненное. Список хранится на устройстве и доступен без сети.</p><div className="task-create"><input value={newTask} onChange={e=>setNewTask(e.target.value)} onKeyDown={e=>e.key==="Enter"&&void addTask()} placeholder="Какое дело нужно выполнить?"/><button className="hero-button" onClick={()=>void addTask()}><Plus size={17}/> ДОБАВИТЬ</button></div><div className="task-board"><div className="task-board-head"><b>СПИСОК ДЕЛ</b><span>{tasks.filter(t=>!t.completed).length} АКТИВНЫХ</span></div>{tasks.length===0?<div className="task-empty"><CalendarDays size={26}/><b>Пока нет задач</b><span>Добавьте первое дело — оно появится здесь</span></div>:tasks.map(t=><div className={"task-row "+(t.completed?"is-done":"")} key={t.id}><button className="task-check" aria-label={t.completed?"Вернуть задачу в работу":"Отметить выполненной"} onClick={()=>t.id!==undefined&&void toggleTask(t.id,t.completed)}>{t.completed?<Check size={16}/>:null}</button><span>{t.title}</span><button className="task-delete" aria-label="Удалить задачу" onClick={()=>t.id!==undefined&&void removeTask(t.id)}>×</button></div>)}</div><small className="demo-note">ОФЛАЙН-ХРАНЕНИЕ · СИНХРОНИЗАЦИЯ МЕЖДУ УСТРОЙСТВАМИ ПОКА НЕ ПОДКЛЮЧЕНА</small></motion.div>}
    </AnimatePresence>
   </main>
   <aside className="right-brief">
    <div className="brief-card"><div className="brief-top"><span>СВОДКА СИСТЕМЫ</span><Activity size={17}/></div><div className="brief-status"><span className="live-dot"/> ИНТЕРФЕЙС ПРЕДПРОСМОТРА</div><div className="brief-stat"><b>07</b><span>ЦИФРОВЫХ СПЕЦИАЛИСТОВ</span></div><div className="brief-stat"><b>02</b><span>ГОТОВЫ К РАБОТЕ</span></div><div className="brief-stat"><b>04</b><span>В РАЗРАБОТКЕ</span></div><div className="brief-progress"><span/><span/><span/><span/><span/><span/><span/></div><small>РАСШИРЕНИЕ ЭКОСИСТЕМЫ</small></div>
    <div className="quote-card"><div className="quote-mark">“</div><p>Большие возможности начинаются с простых полезных дел.</p><span>ПРИНЦИП СОЮЗА</span></div>
    <div className="brief-help"><CircleHelp size={18}/><div><b>Нужна помощь?</b><small>Центр поддержки пользователей</small><button onClick={()=>notify("Центр поддержки будет подключён позже")}>ОТКРЫТЬ <ArrowRight size={12}/></button></div></div>
   </aside>
  </div>
  <nav className="mobile-nav">{nav.map(n=><button key={n.id} className={tab===n.id&&!active?"active":""} onClick={()=>go(n.id)}><n.icon size={19}/><span>{n.label==="СООБЩЕСТВО"?"ЛЮДИ":n.label==="БЮРО"?"ИИ":n.label==="ГЛАВНАЯ"?"ГЛАВНАЯ":n.label==="СВЯЗЬ"?"ЧАТЫ":n.label==="ЛИЧНОЕ ДЕЛО"?"ПРОФИЛЬ":"ДЕЛА"}</span></button>)}</nav>
  <footer className="union-footer"><span>СОЮЗ © 2026</span><span>ЕДИНСТВО · ЗНАНИЯ · ВОЗМОЖНОСТИ</span><span>v{APP_VERSION} · {APP_BUILD.slice(0,7)}</span></footer>
  <AnimatePresence>{toast&&<motion.div className="union-toast" initial={{opacity:0,y:16}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}}>{toast}</motion.div>}</AnimatePresence>
 </div>;
}
function HelperCard({h,onClick}:{h:Helper;onClick:()=>void}){
 return <motion.button whileHover={{y:-4}} whileTap={{scale:.985}} className={"helper-card "+h.color} onClick={onClick}>
  <div className="helper-card-top"><span className="helper-number">СПЕЦИАЛИСТ / {String(helpers.indexOf(h)+1).padStart(2,"0")}</span><span className={h.status==="open"?"card-status open":"card-status locked"}>{h.status==="open"?"ДОСТУПЕН":"СКОРО"}</span></div>
  <div className="helper-illustration"><div className="illustration-grid"/><div className="illustration-orbit"/><Mascot kind={h.icon}/>{h.status==="soon"&&<div className="lock-overlay"><LockKeyhole size={17}/></div>}</div>
  <div className="helper-card-copy"><div className="helper-role">{h.role.toUpperCase()}</div><h3>{h.name}</h3><p>{h.desc}</p><div className="helper-card-bottom"><span>{h.status==="open"?"ПОСТАВИТЬ ЗАДАЧУ":"ПОДРОБНЕЕ"}</span><span className="card-arrow"><ArrowRight size={16}/></span></div></div>
 </motion.button>;
}
createRoot(document.getElementById("root")!).render(<React.StrictMode><QueryClientProvider client={soyuzQueryClient}><App/></QueryClientProvider></React.StrictMode>);
